/* From Uiverse.io by Sharkotech - Tags: card */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 254px;
  background: rgba(211, 211, 211, 0.199);
  position: absolute;
  transition: .3s ease-in-out;
  cursor: pointer;
  box-shadow: 0px 0px 30px -10px rgba(0, 0, 0, 0.3);
}

.__UIV_SCOPE__ #c1 {
  background-color: black;
}

.__UIV_SCOPE__ #c2 {
  background-color: blue;
}

.__UIV_SCOPE__ #c3 {
  background-color: red;
}

.__UIV_SCOPE__ #c4 {
  background-color: green;
}

.__UIV_SCOPE__ .main:hover #c1 {
  transform: translateX(-100px) rotate(-40deg);
}

.__UIV_SCOPE__ .main:hover #c2 {
  transform: translateX(-50px) rotate(-30deg);
}

.__UIV_SCOPE__ .main:hover #c3 {
  transform: translateX(0) rotate(-20deg);
}

.__UIV_SCOPE__ .main:hover #c4 {
  transform: translateX(50px) rotate(-10deg);
}

.__UIV_SCOPE__ #c1:hover {
  transform: translateX(-150px) rotate(0deg) !important;
}

.__UIV_SCOPE__ #c2:hover {
  transform: translateX(-100px) rotate(0deg) !important;
}

.__UIV_SCOPE__ #c3:hover {
  transform: translateX(-50px) rotate(0deg) !important;
}

.__UIV_SCOPE__ #c4:hover {
  transform: translateX(50px) rotate(0deg) !important;
}

.__UIV_SCOPE__ .main {
  display: grid;
  height: 50vmax;
  place-items: center;
}
